{
    public static class АлександрПушкин
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Мой друг, отчизне посвятим души прекрасные порывы!", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Умеренность и аккуратность — вот первые шасти к выздоровлению.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Что может быть лучше, чем любовь, надежда и вера, если они соединены с разумным счастьем?", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Береги честь смолоду, а платье снову.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Волшебница, и с нею век его промчится...", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Увы! Для жизни не годится / Новая броня.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Нет, я не люблю тебя; // Нет, голос мой отрешённый...", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я помню чудное мгновенье: // Передо мной явилась ты...", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Чем меньше женщину мы любим, // Тем легче нравимся мы ей.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Что будет, то будет.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "И жизнь, и слезы, и любовь.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "На свете счастья нет, но есть покой и воля.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Чем меньше женщину мы любим, тем легче нравимся мы ей.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я пережил свои желанья; я утомил свою мечту.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Не мучь меня, не говори упрека: // Кто смеет на меня иметь права?", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Умом Россию не понять, // Аршином общим не измерить...", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Зима!.. Крестьянин, торжествуя, // На дровнях из сеней // Везёт лошадку, полную, // По узкой дорожке.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я памятник себе воздвиг нерукотворный.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "А любовь всё так же простит.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Блажен, кто смолоду был молод, // Блажен, кто вовремя созрел.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Учитесь властвовать собою.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Осень. Дивное очарованье! // Приятна мне твоя прощальная краса — // Люблю я пышное природы увяданье, // В багрец и золото одетые леса...", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Уж небо осенью дышало...", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "И сердце бьётся в упоенье, // И для него воскресли вновь // И божество, и вдохновенье, // И жизнь, и слёзы, и любовь.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "О люди! Кто б то мог подумать, // Что в простом пастухе так много пыла, // А в мудреце — такая робость.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Быть можно, я умру...", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Увы! Моя душа расточена // От скуки и от лени.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я вас любил: любовь ещё, быть может, // В душе моей угасла не совсем;", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Всё было тихо.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Всё для него. Он мне один остался.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Зачем так рано умирать?", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я был рождён для счастья.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Все дни мои прошедшие // Не стоят одной минуты.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "И скучно, и грустно.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "И нет мучительней, чем страсть // Слепая, страстная, шальная.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "И пробуждается поэзия во мне.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "И сердце чует — это мне.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Любви все возрасты покорны.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Любовь, надежда, тихая печаль, // И радость, и тревога.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Не знаю, где и почему, // Но страсть моя неукротима.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Не верь себе, не верь другим.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Не для меня блеск светских сборищ...", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Не мучь меня, не говори упрека.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Не оглядывайся назад.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Не всё ли равно, что будет?", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Обманут, убит.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Он мне один остался.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Осень — прекрасное время года.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Осторожность — лучший друг.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Печально я гляжу на ваше поколенье!", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Покуда сердце бьётся, // Пускай оно любит.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Разум мой, свет мои, // Верю вам.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Свет мой, зеркальце! скажи.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Сижу за решеткой в темнице сырой.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Скучно, грустно.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Так ли ярость преступная // Тревожит мой ум?", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Увы! для жизни не годится // Новая броня.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Ум — лучшее средство.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я жив. Всё это — сон.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я помню: в юности моей // Печалью я томился.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я устал.", Author = "Александр Пушкин" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Александр_Пушкин", Text = "Я — бог.", Author = "Александр Пушкин" },
        };
    }
